-- Applied to sfykcmbgsuzlyksosjny as 20261001124219 v1_auth_rbac_rls.
create type public.app_role as enum ('user','editor','admin');
create table public.user_roles(user_id uuid primary key references auth.users(id) on delete cascade,role public.app_role not null default 'user',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.user_roles enable row level security;
revoke all on public.user_roles from anon,authenticated; grant select on public.user_roles to authenticated;
create policy "users_read_own_role" on public.user_roles for select to authenticated using ((select auth.uid())=user_id);
create schema if not exists private; revoke all on schema private from public,anon,authenticated; grant usage on schema private to authenticated;
create or replace function private.current_app_role() returns public.app_role language sql stable security invoker set search_path='' as $$ select coalesce((select ur.role from public.user_roles ur where ur.user_id=(select auth.uid())),'user'::public.app_role) $$;
revoke all on function private.current_app_role() from public,anon; grant execute on function private.current_app_role() to authenticated;
grant select on public.movies,public.people,public.companies,public.movie_credits,public.movie_companies,public.news_articles,public.image_galleries,public.gallery_images,public.videos,public.short_films,public.ott_platforms,public.ott_titles,public.ott_availability,public.reviews,public.box_office,public.polls,public.poll_options,public.contests,public.tags,public.entity_registry,public.entity_relations,public.entity_tags,public.movie_pulse to anon,authenticated;
grant select,insert,update,delete on public.movies,public.people,public.companies,public.movie_credits,public.movie_companies,public.news_articles,public.image_galleries,public.gallery_images,public.videos,public.short_films,public.ott_platforms,public.ott_titles,public.ott_availability,public.reviews,public.box_office,public.polls,public.poll_options,public.contests,public.tags,public.entity_registry,public.entity_relations,public.entity_tags,public.editorial_items,public.editorial_revisions,public.movie_pulse to authenticated;
revoke all on public.poll_votes,public.contest_entries,public.editorial_items,public.editorial_revisions from anon;
grant select,insert,update,delete on public.poll_votes,public.contest_entries to authenticated;
do $$ declare t text; begin foreach t in array array['movies','people','companies','news_articles','image_galleries','videos','short_films','ott_titles','reviews','polls','contests'] loop
execute format('create policy %I on public.%I for select to anon, authenticated using (status = ''published''::public.content_status or (select private.current_app_role()) in (''editor''::public.app_role,''admin''::public.app_role))',t||'_read',t);
execute format('create policy %I on public.%I for insert to authenticated with check ((select private.current_app_role()) in (''editor''::public.app_role,''admin''::public.app_role))',t||'_staff_insert',t);
execute format('create policy %I on public.%I for update to authenticated using ((select private.current_app_role()) in (''editor''::public.app_role,''admin''::public.app_role)) with check ((select private.current_app_role()) in (''editor''::public.app_role,''admin''::public.app_role))',t||'_staff_update',t);
execute format('create policy %I on public.%I for delete to authenticated using ((select private.current_app_role())=''admin''::public.app_role)',t||'_admin_delete',t); end loop; end $$;
create policy movie_credits_read on public.movie_credits for select to anon,authenticated using(exists(select 1 from public.movies m where m.id=movie_id and m.status='published') or (select private.current_app_role()) in ('editor','admin'));
create policy movie_companies_read on public.movie_companies for select to anon,authenticated using(exists(select 1 from public.movies m where m.id=movie_id and m.status='published') or (select private.current_app_role()) in ('editor','admin'));
