create policy movie_pulse_read on public.movie_pulse for select to anon,authenticated using(exists(select 1 from public.movies m where m.id=movie_id and m.status='published') or (select private.current_app_role()) in ('editor','admin'));
do $$ declare t text; begin foreach t in array array['movie_credits','movie_companies','gallery_images','ott_platforms','ott_availability','poll_options','tags','entity_registry','entity_relations','entity_tags','box_office','movie_pulse'] loop
execute format('create policy %I on public.%I for insert to authenticated with check ((select private.current_app_role()) in (''editor''::public.app_role,''admin''::public.app_role))',t||'_staff_insert',t);
execute format('create policy %I on public.%I for update to authenticated using ((select private.current_app_role()) in (''editor''::public.app_role,''admin''::public.app_role)) with check ((select private.current_app_role()) in (''editor''::public.app_role,''admin''::public.app_role))',t||'_staff_update',t);
